import { readFile, writeFile } from "node:fs/promises";

const all: string = await readFile("./out.txt", "utf8");

const fixed: string[] = all
  .trim()
  .replaceAll("\u001b[94m", "")
  .replaceAll("\u001b[39m", "")
  .replaceAll("\u001b[90m", "")
  .replaceAll("\u001b[37m", "")
  .split("\n")
  .map((line: string): string => line.split(" | ")[2]);

await writeFile("./fixed.txt", fixed.join("\n"));

